import {YARD_FENCES,FREIGHT_GATE} from './yard-layout.js';
import {SITE} from './site-layout.js';
export function siteMapSVG(p){const x=v=>200+v*6.8,y=v=>75+(v+5)*6.8,rect=(r,fill='#2b392d')=>`<rect class="wall" fill="${fill}" x="${x(r.x0)}" y="${y(r.z0)}" width="${(r.x1-r.x0)*6.8}" height="${(r.z1-r.z0)*6.8}"/>`;return `<svg viewBox="0 0 440 390" role="img" aria-label="营业区后方为扩大后的仓库，员工室在建筑右侧且没有外门；电闸在右侧微光通道尽头"><path fill="#384337" d="M35 15h370v22H35z"/><text x="158" y="30">公路 · 不可进入</text>${rect(SITE.shop)}${rect(SITE.stock,'#373b31')}${rect(SITE.office,'#3c3b2e')}<text x="183" y="98">营业区</text><text x="171" y="204">扩大后仓</text><text x="280" y="190" font-size="9">员工室</text><text x="280" y="208" font-size="9">电台·休息</text><path class="door" d="M${x(-.7)} 75h16.3M${x(-6.9)} ${y(9)}h12.2M${x(6.1)} ${y(9)}h12.2M${x(-7.6)} ${y(19)}h21.76M${x(11)} ${y(11.65)}v11.6"/><rect x="135.6" y="79.4" width="11.2" height="38.8" fill="#9b8968"/><rect x="125.8" y="75.9" width="11" height="9.2" fill="#9b8968"/><text x="99" y="136" font-size="9">柜台核验</text><path stroke="#b5aa8a" stroke-width="8" d="M186.4 112v35M213.6 112v35M240.8 112v35"/><g fill="#897b5e">${[-7,0,7].map(v=>`<rect x="${x(v)-6}" y="48" width="12" height="21"/>`).join('')}</g><text x="172" y="47">加油区</text><circle cx="104" cy="10" r="3" fill="#aaa385"/><text x="63" y="8" font-size="9">末班公交站</text><rect x="151" y="251" width="23" height="58" fill="#675e4b"/><text x="140" y="326">打开的配送货厢</text><rect x="${x(SITE.breaker.x)-4}" y="${y(SITE.breaker.z)-4}" width="8" height="8" fill="#b18142"/><path fill="#47513a" d="M277 245h45v35h-45z"/><text x="280" y="266" font-size="8">高草／废品</text>${YARD_FENCES.map(p=>`<path d="M${x(p.x-p.w/2)} ${y(p.z-p.d/2)}L${x(p.x+p.w/2)} ${y(p.z+p.d/2)}" stroke="#aa8052" stroke-width="2"/>`).join('')}<text x="270" y="304" font-size="9">卸货院围栏 · 禁止穿行</text><text x="345" y="246">电闸</text><path d="M${x(.5)} ${y(-5.8)}L${x(19.65)} ${y(-5.8)}L${x(19.65)} ${y(18.0)}" fill="none" stroke="#ccad69" stroke-width="2" stroke-dasharray="3 4"/><text x="330" y="348" font-size="9">货运铁门</text><text x="331" y="177" font-size="9">微光通道</text><circle class="dot" cx="${x(p.x)}" cy="${y(p.z)}" r="4"/><path d="M${x(p.x)} ${y(p.z)}l${-Math.sin(p.yaw)*11} ${-Math.cos(p.yaw)*11}" stroke="#ecc67a" stroke-width="2"/></svg>`;}
